function selectMood(emoji: string, label: string) {
  moodEmoji.value = emoji
  moodLabel.value = label
  showMoodPicker.value = false
  markDirty()
}

function clearMood() {
  moodEmoji.value = ''
  moodLabel.value = ''
  markDirty()
}

// ── Location ──────────────────────────────────────────────────────────────────
function requestGeolocation() {
  if (!navigator.geolocation) {
    locationError.value = 'Geolocation is not supported by your browser.'
    return
  }
  locationLoading.value = true
  locationError.value   = ''

  navigator.geolocation.getCurrentPosition(
    async (position) => {
      latitude.value  = position.coords.latitude
      longitude.value = position.coords.longitude
      locationSource.value = 'geolocation'

      // Use Nominatim (OpenStreetMap) — no API key required, calls are proxied
      // or direct from browser (public endpoint, no auth needed)
      try {
        const res = await fetch(
          `https://nominatim.openstreetmap.org/reverse?lat=${latitude.value}&lon=${longitude.value}&format=json`,
          { headers: { 'Accept-Language': 'en' } }
        )
        const data = await res.json()
        const addr = data.address ?? {}
        const parts = [
          addr.suburb ?? addr.village ?? addr.town ?? addr.city_district,
          addr.city ?? addr.municipality,
          addr.state ?? addr.province,
        ].filter(Boolean)
        locationName.value = parts.length > 0 ? parts.join(', ') : data.display_name ?? 'Unknown location'
      } catch {
        locationName.value = `${latitude.value!.toFixed(4)}, ${longitude.value!.toFixed(4)}`
      }

      locationLoading.value = false
      showLocationPicker.value = false
      markDirty()
    },
    (err) => {
      locationLoading.value = false
      if (err.code === err.PERMISSION_DENIED) {
        locationError.value = 'Location permission denied. You can search for a location manually.'
      } else if (err.code === err.POSITION_UNAVAILABLE) {
        locationError.value = 'Location unavailable. Try searching manually.'
      } else {
        locationError.value = 'Location request timed out. Try searching manually.'
      }
    },
    { timeout: 10000, maximumAge: 60000 }
  )
}

async function searchLocation() {
  if (!manualLocationInput.value.trim()) return
  locationLoading.value = true
  locationError.value   = ''
  try {
    const res = await fetch(
      `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(manualLocationInput.value)}&format=json&limit=1`,
      { headers: { 'Accept-Language': 'en' } }
    )
    const results = await res.json()
    if (results.length > 0) {
      const r = results[0]
      latitude.value  = parseFloat(r.lat)
      longitude.value = parseFloat(r.lon)
      locationName.value   = r.display_name
      locationSource.value = 'search'
      showLocationPicker.value = false
      markDirty()
    } else {
      locationError.value = 'No results found. Try a different search term.'
    }
  } catch {
    locationError.value = 'Search failed. Please try again.'
  } finally {
    locationLoading.value = false
  }
}

function setManualLocation() {
  if (!manualLocationInput.value.trim()) return
  locationName.value   = manualLocationInput.value.trim()
  latitude.value       = null
  longitude.value      = null
  locationSource.value = 'manual'
  showLocationPicker.value = false
  manualLocationInput.value = ''
  markDirty()
}

function clearLocation() {
  locationName.value   = ''
  latitude.value       = null
  longitude.value      = null
  locationSource.value = null
  locationError.value  = ''
  markDirty()
}

// ── Tags ──────────────────────────────────────────────────────────────────────
function addTag() {
  const t = tagInput.value.trim().replace(/,/g, '')
  if (t && !tags.value.includes(t) && tags.value.length < 10) {
    tags.value.push(t)
    markDirty()
  }
  tagInput.value = ''
}

function removeTag(tag: string) {
  tags.value = tags.value.filter(t => t !== tag)
  markDirty()
}

function handleTagKeydown(e: KeyboardEvent) {
  if (e.key === 'Enter' || e.key === ',') {
    e.preventDefault()
    addTag()
  }
}

// ── Save ──────────────────────────────────────────────────────────────────────
let savedEntryId = entryId
async function handleSave() {
  if (!canSave.value) return
  saving.value   = true
  saveError.value = ''

  const payload = {
    title:            title.value.trim(),
    content:          content.value.trim(),
    entry_date:       date.value,
    mood_emoji:       moodEmoji.value || null,
    mood_label:       moodLabel.value || null,
    // Keep legacy mood field null for custom emoji moods
    mood:             null as string | null,
    location_name:    locationName.value || null,
    latitude:         latitude.value,
    longitude:        longitude.value,
    location_source:  locationSource.value,
    visibility: 'private' as const,
    tags: tags.value,
  }

  try {

    if (savedEntryId) {
      await store.updateEntry(savedEntryId, payload)
    } else {
      const created = await store.createEntry(payload as Parameters<typeof store.createEntry>[0])
      savedEntryId = created.id
    }

    // Keep pending files on failure; retry updates the saved entry instead of creating a duplicate.
    while (photosToDelete.value.length) {
      await api.delete(`/journal/${savedEntryId}/media/${photosToDelete.value[0]}`)
      photosToDelete.value.shift()
    }
    uploadingPhotos.value = true
    while (newPhotos.value.length) {
      const formData = new FormData()
      formData.append('file', newPhotos.value[0])
      await api.post(`/journal/${savedEntryId}/media`, formData)
      newPhotos.value.shift()
    }
    uploadingPhotos.value = false

    saveSuccess.value = true
    isDirty.value     = false
    await router.push({ name: 'journal' })
  } catch (err: unknown) {
    const e = err as { response?: { status?: number; data?: { message?: string; errors?: Record<string, string[]> } } }
    const status = e?.response?.status
    const data   = e?.response?.data
    if (status === 422 && data?.errors) {
      const firstError = Object.values(data.errors)[0]?.[0]
      saveError.value = firstError ?? 'Please check the highlighted fields.'
    } else if (!e?.response) {
      saveError.value = `You're currently offline or the server is unavailable.`
    } else {
      saveError.value = data?.message ?? `We couldn't save your journal entry right now. Please try again.`
    }
  } finally {
    saving.value = false
    uploadingPhotos.value = false
  }
}

function handleRemoveExistingPhoto(photoId: string) {
  photosToDelete.value.push(photoId)
  existingPhotos.value = existingPhotos.value.filter(p => p.id !== photoId)
  markDirty()
}

// Close pickers when clicking outside
function closePickers() {
  showMoodPicker.value     = false
  showLocationPicker.value = false
}
</script>

